import "@oomol-lab/connector";

declare module "@oomol-lab/connector" {
  interface ActionRegistry {
    /** Retrieve an issued IssueBadge record by encrypted issue ID, including recipient details, metadata, verification URL, and PDF URL. */
    "issue_badge.get_issued_badge": {
      input: {
        /**
         * Encrypted issue ID.
         * @minLength 1
         */
        id: string;
      };
      output: {
        /** Whether the request succeeded. */
        success?: boolean;
        /** An issued badge with recipient details and verification URLs. */
        data?: {
          /** Encrypted issue ID. */
          issue_id?: string;
          /** Recipient's full name. */
          recipient_name?: string;
          /** Recipient's email address. */
          recipient_email?: string;
          /** Recipient's phone number. */
          recipient_phone?: string;
          /** Encrypted badge ID. */
          badge_id?: string;
          /** Badge name. */
          badge_name?: string;
          /** Issuing organization name. */
          organization_name?: string;
          /** Badge issue date. */
          issue_date?: string;
          /** Badge expiration date, if set. */
          expire_date?: string | null;
          /** Badge serial number, if set. */
          serial_number?: string | null;
          /** Additional notes, if set. */
          memo?: string | null;
          /** Public verification URL. */
          public_url?: string;
          /** PDF download URL. */
          pdf_url?: string;
          /** Custom field values and additional metadata. */
          metadata?: Record<string, unknown> | null;
          /** Record creation timestamp. */
          created_at?: string;
          /** Record last update timestamp. */
          updated_at?: string;
          [key: string]: unknown;
        };
        [key: string]: unknown;
      };
    };
    /** Issue an existing IssueBadge template to a recipient and create a public verification URL. Providing an email address triggers a notification email. Reuse an idempotency key to retrieve the existing issuance without issuing it again. */
    "issue_badge.issue_badge": {
      input: {
        /**
         * Encrypted badge ID from list_badges.
         * @minLength 1
         */
        badge_id: string;
        /**
         * Recipient's full name.
         * @minLength 1
         * @maxLength 200
         */
        name: string;
        /**
         * Recipient's email address for notification.
         * @format email
         */
        email?: string;
        /** Recipient's phone number. */
        phone?: string;
        /**
         * Unique key to prevent duplicate issuance. Generated by IssueBadge when omitted.
         * @minLength 1
         * @maxLength 100
         */
        idempotency_key?: string;
        /** Custom field values and additional metadata. */
        metadata?: Record<string, unknown>;
      };
      output: {
        /** Whether the request succeeded. */
        success?: boolean;
        /** Encrypted issue ID for tracking. */
        IssueId?: string;
        /** Public verification URL. */
        publicUrl?: string;
        [key: string]: unknown;
      };
    };
    /** List up to 100 badge templates in your IssueBadge organization. The API does not expose pagination for this list. */
    "issue_badge.list_badges": {
      input: Record<string, never>;
      output: {
        /** Whether the request succeeded. */
        success?: boolean;
        /** Response message. */
        message?: string;
        /** Available badge templates. */
        data?: Array<{
          /** Encrypted badge ID. */
          id?: string;
          /** Badge name. */
          name?: string;
          [key: string]: unknown;
        }>;
        [key: string]: unknown;
      };
    };
    /** List issued IssueBadge records with pagination and optional badge, recipient name, and recipient email filters. */
    "issue_badge.list_issued_badges": {
      input: {
        /**
         * Filter by encrypted badge ID.
         * @minLength 1
         */
        badge_id?: string;
        /** Search by recipient name using a partial match. */
        recipient_name?: string;
        /** Search by recipient email using a partial match. */
        recipient_email?: string;
        /**
         * Page number, starting at 1. Defaults to 1.
         * @minimum 1
         */
        page?: number;
        /**
         * Items per page, up to 100. Defaults to 10.
         * @minimum 1
         * @maximum 100
         */
        per_page?: number;
      };
      output: {
        /** Whether the request succeeded. */
        success?: boolean;
        /** Issued badges matching the filters. */
        data?: Array<{
          /** Encrypted issue ID. */
          issue_id?: string;
          /** Recipient's full name. */
          recipient_name?: string;
          /** Recipient's email address. */
          recipient_email?: string;
          /** Recipient's phone number. */
          recipient_phone?: string;
          /** Encrypted badge ID. */
          badge_id?: string;
          /** Badge name. */
          badge_name?: string;
          /** Issuing organization name. */
          organization_name?: string;
          /** Badge issue date. */
          issue_date?: string;
          /** Badge expiration date, if set. */
          expire_date?: string | null;
          /** Badge serial number, if set. */
          serial_number?: string | null;
          /** Additional notes, if set. */
          memo?: string | null;
          /** Public verification URL. */
          public_url?: string;
          /** PDF download URL. */
          pdf_url?: string;
          /** Custom field values and additional metadata. */
          metadata?: Record<string, unknown> | null;
          /** Record creation timestamp. */
          created_at?: string;
          /** Record last update timestamp. */
          updated_at?: string;
          [key: string]: unknown;
        }>;
        /** Pagination metadata. */
        pagination?: {
          /** Current page number. */
          current_page?: number;
          /** Items per page. */
          per_page?: number;
          /** Total number of matching records. */
          total?: number;
          /** Total number of pages. */
          total_pages?: number;
          /** Whether another page is available. */
          has_more?: boolean;
          [key: string]: unknown;
        };
        [key: string]: unknown;
      };
    };
  }
}
